//! How a letter typed without its mark is written, for every part of speech.
//! Each rule reads the letter before it, the letter, the letters after it and,
//! after the word's end, the part of speech (`#` is the word's start or end):
//! the longest one that matches decides (`dus#a` → `u`; `tus#a` → `u`; `rus#a` → `u`), giving each way of writing the
//! letter with how many of the dictionary's letters in that place are written
//! so. A root comes first: the beginning of a word through a letter and two
//! past it, where nine in ten of the dictionary's words with a form beginning
//! so (two or more) write the letter one way the rules don't (`abbati` → `ā`: a word typed `abbati…` writes its `a` `ā`).

